import fs from "node:fs/promises";
import path from "node:path";

const directory = path.resolve("packages/db/migrations");
const output = path.resolve("packages/db/src/migrations.generated.ts");
const files = (await fs.readdir(directory)).filter((name) => name.endsWith(".sql")).sort();
const migrations = [];
for (const file of files) {
  migrations.push({
    version: file,
    source: await fs.readFile(path.join(directory, file), "utf8"),
  });
}

const source = `// AUTO-GENERATED by scripts/generate-migration-bundle.mjs.\n// Do not edit by hand; edit packages/db/migrations/*.sql instead.\n\nexport const databaseMigrations = ${JSON.stringify(migrations, null, 2)} as const;\n\nexport const latestMigrationVersion = databaseMigrations.at(-1)?.version ?? null;\n`;
await fs.writeFile(output, source, "utf8");
console.log(`generated ${path.relative(process.cwd(), output)} (${migrations.length} migrations)`);
